// The named export is a VIEW of the gated PIXEL_BLOCKS entry — one byte array,
// so the AC-1/AC-4 byte gate on PIXEL_BLOCKS covers every consumer of COMCL5.
// (jt1-3 review R1: a second literal here was 871 ungated bytes.)
const comcl5Block = PIXEL_BLOCKS.find((b) => b.name === 'COMCL5')
if (!comcl5Block) throw new Error('COMCL5 block missing from PIXEL_BLOCKS')
export const COMCL5: { bytes: number[]; anchor: SourceAnchor } = {
  anchor: comcl5Block.anchor,
  bytes: comcl5Block.bytes,
}

export const DEFERRED: DeferredBlock[] = []

/**
 * The COMCL5 un-compactor, transcribed from UNCOM/REST (SYSTEM.SRC:937-1023),
 * entered from NEWCL5 (:927-929) at pixel origin (0x1B*2, 0xD3) = (54, 211).
 *
 * It is an Elias-gamma BIT stream, not the value/run byte pairs a first reading
 * suggests. Per token:
 *   - a unary prefix counts bits up to and including the first 1 (UNCLP :939-947)
 *   - REST (:1012-1023) reads that many more bits onto an implicit leading 1
 *   - run length = that value minus 2 (\`SUBA #2\`, :949)
 *   - three more bits give a colour code; 0 stays nibble 0, 1..7 map to 8..14
 *     (\`ANDA #\$07 / BEQ / ADDA #8-1\`, :964-966) — which is why the expansion can
 *     only ever emit {0} u {8..14}
 *   - run length 0 means end of LINE, or end of IMAGE when the colour bits are
 *     also 0 (:955-957)
 *
 * Pure and total: same input, same output, input never mutated.
 */
export function expandComcl5(bytes: readonly number[]): ExpandedImage {
  let u = 0 // REG.U — index of the next compressed byte
  let b = 0 // REG.B — bit shift register, left-aligned with a trailing sentinel

  /** ASLB: shift the next bit out, reloading when the sentinel falls out. */
  const nextBit = (): number => {
    const shifted = (b << 1) & 0xff
    const carry = (b >> 7) & 1
    if (shifted === 0) {
      // The sentinel reached bit 7 and fell out: LDB ,U+ / ASLB / INCB.
      const x = bytes[u++] ?? 0
      b = ((x << 1) & 0xff) | 1
      return (x >> 7) & 1
    }
    b = shifted
    return carry
  }

  /** REST: read \`count\` bits onto an implicit leading 1. */
  const rest = (count: number): number => {
    let a = 1
    for (let i = 0; i < count; i++) a = ((a << 1) | nextBit()) & 0xff
    return a
  }

  const pixels: number[] = []
  const rowLengths: number[] = []
  let x = 0
  let maxX = 0
  let lines = 0

  for (;;) {
    let n = 0
    for (;;) {
      n++
      if (nextBit()) break
      if (n > 16) return { width: maxX, height: lines, pixels, rowLengths } // malformed stream
    }
    const run = (rest(n) - 2) & 0xff
    let colour = rest(3) & 0x07

    if (run === 0) {
      if (colour === 0) break // end of image
      // End of line: X reloads to the line start, Y advances one scanline. A
      // line only counts once it has pixels, so a trailing end-of-line
      // immediately before end-of-image does not invent a blank row.
      if (x > 0) {
        lines++
        rowLengths.push(x)
      }
      if (x > maxX) maxX = x
      x = 0
      continue
    }

    if (colour !== 0) colour += 8 - 1
    for (let i = 0; i < run; i++) {
      pixels.push(colour)
      x++
    }
  }

  if (x > 0) {
    lines++
    rowLengths.push(x)
  }
  if (x > maxX) maxX = x
  return { width: maxX, height: lines, pixels, rowLengths }
}

/**
 * jt3-6 — the ASH1R/L ptero-dissolve decoder, transcribed from CLIFER, the
 * routine PTEASH JMPs into (JOUSTRV4.SRC:4604-4631) — the consumer that
 * ESTABLISHES the run-length format open-questions §5 flagged "value/run pairs?".
 *
 * CLIFER reads one byte at a time (`LDA ,Y+`, JOUSTRV4.SRC:4605 "lo nybble is
 * color, hi nybble is length"):
 *   - $00 (length and colour both 0) ENDS the image (`BEQ 1$`, :4606 → RTS :4631);
 *   - the colour is the LOW nibble, replicated across a screen byte (`ANDA #$0F`
 *     / `LDB #17` / `MUL`, :4607-4609) — a byte of two 4bpp pixels of that colour;
 *   - the length is the HIGH nibble (`ANDA #$F0` then four `LSRA`, :4611-4615);
 *   - a length-0 (but non-zero) byte ENDS the line, the next row one down
 *     (`BNE 3$`, :4616; fall-through :4617-4619);
 *   - a run writes `length` screen-bytes of the colour, and the LAST byte of the
 *     run is ONE pixel only — its low nibble cleared (`CMPA #1` / `ANDB #$F0`,
 *     :4622-4624 "last byte is always one pixel to enhance debris image").
 *
 * Decodes ONE frame from `offset`, returning the expanded image and the offset
 * of the NEXT frame (just past the $00). The $9800 screen-bounds clip (:4627) is
 * a VRAM-address guard, not a data property, so a logical decode from column 0
 * does not apply it. Pure and total: `bytes` is never mutated.
 */
export function expandAsh(
  bytes: readonly number[],
  offset = 0,
): { image: ExpandedImage; next: number } {
  const pixels: number[] = []
  const rowLengths: number[] = []
  let x = 0
  let width = 0
  let i = offset

  /** Close the current row: record its length, widen the frame, reset X. */
  const endLine = (): void => {
    if (x > 0) {
      rowLengths.push(x)
      if (x > width) width = x
    }
    x = 0
  }

  for (;;) {
    const b = bytes[i++]
    if (b === undefined || b === 0) break // $00 — end of image
    const colour = b & 0x0f // lo nybble is colour
    const length = (b >> 4) & 0x0f // hi nybble is length
    if (length === 0) {
      endLine() // length nybble 0 (byte non-zero) — end of line
      continue
    }
    for (let k = 0; k < length; k++) {
      // Each screen byte is two pixels of the colour; the LAST byte of the run
      // keeps only its high nibble (low nibble 0) — the one-pixel debris tail.
      pixels.push(colour)
      pixels.push(k === length - 1 ? 0 : colour)
      x += 2
    }
  }
  endLine() // flush the final row (the image ends without an end-of-line marker)

  return { image: { width, height: rowLengths.length, pixels, rowLengths }, next: i }
}

/**
 * jt3-6 — all ASH animation frames (PTERA1/PTERA2/PTERA3), decoded in order by
 * walking `expandAsh` across the $00 end-of-image boundaries. The dissolve is a
 * three-frame animation (`LDA #3` "3 FRAME ANIMATION", JOUSTRV4.SRC:1388), so
 * the 172-byte ASH1R/L stream yields exactly 3 frames. Pure; input never mutated.
 */
export function expandAshFrames(bytes: readonly number[]): ExpandedImage[] {
  const frames: ExpandedImage[] = []
  let offset = 0
  while (offset < bytes.length) {
    const { image, next } = expandAsh(bytes, offset)
    frames.push(image)
    if (next <= offset) break // safety — never loop on a malformed stream
    offset = next
  }
  return frames
}

